"use client";

/* Effects: the craft from the Morris OS guest key card, made reusable. They're
   opt-in and for special moments, like a guest's key card, a welcome or one
   hero element, and no more than 1 or 2 on a screen. The rules are in
   obvious's CLAUDE.md under "Effects".

   The engine is in fx.ts, with no React in it. Colours are --fx-* custom
   properties in effects.css, defaulting to the card's blue-violet. Every piece
   is still and in its final state when someone has asked for less motion. */
import "./effects.css";

import {
  createElement,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import {
  askGyro,
  fnv,
  GLYPHS,
  glowCursor,
  maskUrl,
  reduced,
  scramble,
  seal,
  tilt,
  waveField,
  watchGyroPermission,
  type SealOptions,
} from "./fx";

export { seal, waveField, fnv, type SealOptions } from "./fx";

type Vars = CSSProperties & Record<`--${string}`, string | number | undefined>;

/* ---------- HoloSurface ---------- */

/* A surface that leans towards the pointer, a finger or the phone's tilt.
   Children can read where it is from --fx-x and --fx-y (-1 to 1), --fx-m (0 to
   1) and --fx-a (an angle). className and style go on the part that tilts, so
   that's the card. */
export function HoloSurface({
  children,
  className,
  style,
  tilt: degrees = 8,
  perspective = 1100,
  drift = true,
  gyro = true,
  light = true,
}: {
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
  /* Most it leans sideways, in degrees. Up and down is three quarters of it. */
  tilt?: number;
  perspective?: number;
  /* A slow drift when nobody's touching it. */
  drift?: boolean;
  /* Follow the phone's tilt. On iOS that needs useGyroPermission too. */
  gyro?: boolean;
  /* A highlight that moves across it and a lit edge on the side facing the light. */
  light?: boolean;
}) {
  const stage = useRef<HTMLDivElement>(null);
  useEffect(() => (stage.current ? tilt(stage.current, { drift, gyro }) : undefined), [drift, gyro]);
  const vars: Vars = { "--fx-tilt": `${degrees}deg`, "--fx-perspective": `${perspective}px` };
  return (
    <div ref={stage} className="ob-fx-surface" style={vars}>
      <div className={"ob-fx-surface-tilt" + (className ? " " + className : "")} style={style}>
        {children}
        {light && (
          <>
            <span className="ob-fx-surface-light" aria-hidden="true">
              <span />
            </span>
            <span className="ob-fx-surface-rim" aria-hidden="true" />
          </>
        )}
      </div>
    </div>
  );
}

/* iOS sends no tilt until someone taps to allow it. needed turns true on a
   touch screen that has sent nothing after a moment; show a button that calls
   ask from its onClick:

     const gyro = useGyroPermission();
     {gyro.needed && <button onClick={gyro.ask}>Tilt to see the hologram</button>} */
export function useGyroPermission(wait = 1200) {
  const [needed, setNeeded] = useState(false);
  useEffect(() => watchGyroPermission(setNeeded, wait), [wait]);
  return {
    needed,
    ask: () => {
      askGyro();
      setNeeded(false);
    },
  };
}

/* ---------- Holo ---------- */

const FILM = [1, 2, 3, 4, 5, 6, 1];

/* Thin-film colour on engraved lines: the lines drawn faintly, and the same
   lines as a mask over colour that shifts with the surface's angle. Give it
   paths (with their viewBox), an image src whose shape is the mask, or SVG
   children to use as the mask. */
export function Holo({
  paths,
  viewBox = "0 0 100 100",
  strokeWidth = 1,
  src,
  children,
  strength = 1,
  base = 0.12,
  className,
  style,
}: {
  paths?: string | string[];
  viewBox?: string;
  strokeWidth?: number;
  src?: string;
  /* SVG content (paths, shapes, text) in viewBox units. Its own colours don't matter. */
  children?: ReactNode;
  /* How strong the colour is, 0 to 1. */
  strength?: number;
  /* How strong the faint engraving is, 0 to 1. */
  base?: number;
  className?: string;
  style?: CSSProperties;
}) {
  const [, , vw, vh] = viewBox.split(/[\s,]+/).map(Number);
  const vars: Vars = { "--fx-holo-strength": strength, "--fx-holo-base": base, aspectRatio: `${vw} / ${vh}`, ...style };
  if (children) return <HoloSvg viewBox={viewBox} vars={vars} className={className}>{children}</HoloSvg>;
  return <HoloMask paths={paths} viewBox={viewBox} strokeWidth={strokeWidth} src={src} vars={vars} className={className} />;
}

/* Paths and images become a CSS mask: a picture the compositor moves light
   across, which stays cheap however many lines there are. */
function HoloMask({ paths, viewBox, strokeWidth, src, vars, className }: { paths?: string | string[]; viewBox: string; strokeWidth: number; src?: string; vars: Vars; className?: string }) {
  const [url, setUrl] = useState<string | null>(src ?? null);
  const list = paths ? (Array.isArray(paths) ? paths : [paths]) : [];
  const sig = src ?? `${viewBox}|${strokeWidth}|${fnv(list.join("|"))}`;
  useEffect(() => {
    if (src) return setUrl(src);
    if (!list.length) return setUrl(null);
    const u = maskUrl(viewBox, list, strokeWidth);
    setUrl(u);
    return () => URL.revokeObjectURL(u);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sig]);
  return (
    <div
      className={"ob-fx-holo" + (className ? " " + className : "")}
      data-ready={url ? "" : undefined}
      style={{ ...vars, "--fx-mask": url ? `url("${url}")` : undefined } as Vars}
      aria-hidden="true"
    >
      <div className="ob-fx-holo-base" />
      <div className="ob-fx-holo-colour">
        <div className="ob-fx-holo-counter">
          <div className="ob-fx-holo-film">
            <div className="ob-fx-holo-bands" />
          </div>
        </div>
      </div>
    </div>
  );
}

/* SVG children become an SVG mask, so text and shapes work as they are. */
function HoloSvg({ viewBox, vars, className, children }: { viewBox: string; vars: Vars; className?: string; children: ReactNode }) {
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const [vx, vy, vw, vh] = viewBox.split(/[\s,]+/).map(Number);
  const box = (k: number) => ({ x: vx - vw * k, y: vy - vh * k, width: vw * (1 + 2 * k), height: vh * (1 + 2 * k) });
  return (
    <svg className={"ob-fx-holo ob-fx-holo-svg" + (className ? " " + className : "")} viewBox={viewBox} style={vars} aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id={`${id}-film`} gradientUnits="userSpaceOnUse" x1={vx} y1={vy} x2={vx + vw * 0.21} y2={vy + vw * 0.05} spreadMethod="repeat">
          {FILM.map((n, i) => (
            <stop key={i} offset={i / (FILM.length - 1)} style={{ stopColor: `var(--fx-film-${n})` }} />
          ))}
        </linearGradient>
        <radialGradient id={`${id}-light`}>
          <stop offset="0" stopColor="white" stopOpacity="1" />
          <stop offset="0.35" stopColor="white" stopOpacity="0.6" />
          <stop offset="0.7" stopColor="white" stopOpacity="0.18" />
          <stop offset="1" stopColor="white" stopOpacity="0" />
        </radialGradient>
        <mask id={`${id}-lines`} style={{ maskType: "alpha" }}>
          <g fill="white" stroke="white">{children}</g>
        </mask>
        <mask id={`${id}-lit`} style={{ maskType: "alpha" }}>
          <rect className="ob-fx-holo-svg-light" {...box(0.3)} fill={`url(#${id}-light)`} />
        </mask>
      </defs>
      <g className="ob-fx-holo-base">{children}</g>
      <g className="ob-fx-holo-colour" mask={`url(#${id}-lines)`}>
        <g mask={`url(#${id}-lit)`}>
          <rect className="ob-fx-holo-svg-bands" {...box(0.5)} fill={`url(#${id}-film)`} />
        </g>
      </g>
    </svg>
  );
}

/* ---------- Guilloche ---------- */

/* A seal made from a seed, in Holo. The same seed always draws the same seal,
   so a guest's name and dates can make theirs. variant="field" draws fine
   waves across the whole box instead, for behind a card. */
export function Guilloche({
  seed,
  variant = "seal",
  rings = 3,
  spin = true,
  depth = 0.5,
  strokeWidth = 0.85,
  width = 856,
  height = 540,
  options,
  className,
  style,
}: {
  seed: string;
  variant?: "seal" | "field";
  rings?: number;
  /* Rings turn against each other, very slowly, so the moiré between them shifts. */
  spin?: boolean;
  /* How far the outer rings slide against the inner ones as it tilts. */
  depth?: number;
  strokeWidth?: number;
  /* The field's size in its own units. */
  width?: number;
  height?: number;
  options?: Omit<SealOptions, "rings">;
  className?: string;
  style?: CSSProperties;
}) {
  const opts = JSON.stringify(options ?? {});
  const s = useMemo(() => (variant === "seal" ? seal(seed, { ...JSON.parse(opts), rings }) : null), [variant, seed, rings, opts]);
  const field = useMemo(() => (variant === "field" ? waveField(seed, { width, height }) : ""), [variant, seed, width, height]);
  const cls = "ob-fx-guilloche" + (className ? " " + className : "");
  if (!s) return <Holo className={cls} style={style} paths={field} viewBox={`0 0 ${width} ${height}`} strokeWidth={1.6} strength={0.4} base={0.08} />;
  const layers = [...s.rings, s.border].filter(Boolean);
  return (
    <div className={cls} style={{ aspectRatio: "1", ...style }} aria-hidden="true">
      {layers.map((d, n) => (
        <div
          key={n}
          className="ob-fx-guilloche-ring"
          data-spin={spin ? (n % 2 ? "reverse" : "normal") : undefined}
          data-edge={n === s.rings.length ? "" : undefined}
          style={{ "--fx-depth": (n * depth).toFixed(2), "--fx-spin": `${n === s.rings.length ? 420 : 260 - n * 30}s` } as Vars}
        >
          <Holo paths={d} viewBox={s.viewBox} strokeWidth={strokeWidth} strength={n === 0 ? 1 : 0.4} base={n === 0 ? 0.17 : 0.09} />
        </div>
      ))}
    </div>
  );
}

/* ---------- EncryptedText ---------- */

/* Now and then the letters flip to symbols and come back. Each letter keeps
   its place under its symbol, so the word never changes width. One word on
   the page at a time, and never in the first `delay` ms. Screen readers get
   the plain text. */
export function EncryptedText({
  text,
  delay = 4000,
  glyphs = GLYPHS,
  as = "span",
  className,
}: {
  text: string;
  delay?: number;
  glyphs?: string[];
  as?: "span" | "p" | "h1" | "h2" | "h3" | "strong";
  className?: string;
}) {
  const [g, setG] = useState<(string | null)[]>([]);
  const [lit, setLit] = useState<boolean[]>([]);
  const glyphKey = glyphs.join("");
  useEffect(() => {
    setG([]);
    setLit([]);
    return scramble({
      text,
      delay,
      glyphs,
      onStep: (a, b) => {
        setG(a);
        setLit(b);
      },
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, delay, glyphKey]);
  return createElement(
    as,
    { className: "ob-fx-enc" + (className ? " " + className : "") },
    <span className="ob-fx-sr">{text}</span>,
    <span className="ob-fx-enc-letters" aria-hidden="true">
      {Array.from(text).map((ch, i) => (
        <span key={i} data-g={g[i] ?? undefined} data-lit={lit[i] ? "" : undefined}>
          {ch}
        </span>
      ))}
    </span>,
  );
}

/* ---------- GlowText ---------- */

/* Soft light drifting behind the words, and now and then a sheen passing
   through them. The words themselves stay solid in the theme's text colour,
   so contrast is the same as without it. */
export function GlowText({
  children,
  as = "span",
  sheen = true,
  className,
}: {
  children: string;
  as?: "span" | "p" | "h1" | "h2" | "h3" | "strong";
  sheen?: boolean;
  className?: string;
}) {
  return createElement(
    as,
    { className: "ob-fx-glow-text" + (className ? " " + className : "") },
    <span className="ob-fx-glow" aria-hidden="true" />,
    <span className="ob-fx-glow-ink">{children}</span>,
    sheen ? (
      <span className="ob-fx-sheen" aria-hidden="true">
        <span className="ob-fx-sheen-band">
          <span className="ob-fx-sheen-text">{children}</span>
        </span>
      </span>
    ) : null,
  );
}

/* ---------- BorderLight ---------- */

/* A slow light going round the border. For the one button or card on a
   screen that matters most. Set radius to match what's inside. */
export function BorderLight({
  children,
  radius,
  block = false,
  className,
}: {
  children: ReactNode;
  /* Any CSS length, like var(--ds-radius-lg). Defaults to --ds-radius-md. */
  radius?: string;
  /* Fill the width, for a card. Otherwise it sits inline, for a button. */
  block?: boolean;
  className?: string;
}) {
  return (
    <span
      className={"ob-fx-border-light" + (block ? " is-block" : "") + (className ? " " + className : "")}
      style={radius ? ({ "--fx-radius": radius } as Vars) : undefined}
    >
      {children}
      <span className="ob-fx-border-light-ring" aria-hidden="true">
        <span />
      </span>
    </span>
  );
}

/* ---------- GlowCursor ---------- */

/* Put one on the page. A soft light follows the mouse, and the hairline
   borders of anything with data-fx-rim light up as it gets near. Nothing on a
   touch screen. */
export function GlowCursor({ reach = 220 }: { reach?: number }) {
  const light = useRef<HTMLDivElement>(null);
  useEffect(() => glowCursor(light.current, reach), [reach]);
  return <div ref={light} className="ob-fx-cursor" aria-hidden="true" />;
}

/* For reduced(), so an app can check the same thing the effects do. */
export { reduced };

/* The engine behind effects.tsx, with no React in it, so the docs site runs the
   same code an app gets. Everything here is either pure (the seal and the wave
   field) or takes an element and hands back a teardown, which is the shape a
   React effect wants.

   It came out of the guest key card in Morris OS. */

export const reduced = () =>
  typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/* ---------- the seal ---------- */

/* FNV-1a, 32 bits. */
export function fnv(text: string) {
  let h = 2166136261;
  for (const ch of text) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
  return h;
}

/* Math.sin is allowed to differ by a hair between JavaScript engines, so Node
   and Safari could round a point differently and the server's seal wouldn't
   match the phone's. This uses only + and *, which every engine does the same. */
const PI = 3.141592653589793;
const HALF = 1.5707963267948966;
const TAU = 6.283185307179586;
export function sin(x: number) {
  x -= TAU * Math.round(x / TAU);
  if (x > HALF) x = PI - x;
  else if (x < -HALF) x = -PI - x;
  const s = x * x;
  return x * (1 - (s / 6) * (1 - (s / 20) * (1 - (s / 42) * (1 - (s / 72) * (1 - (s / 110) * (1 - s / 156))))));
}
export const cos = (x: number) => sin(x + HALF);

const f1 = (n: number) => (Math.round(n * 10) / 10).toFixed(1);

export type SealOptions = {
  /* How many rings, 1 to 12. */
  rings?: number;
  /* Radius of the innermost ring. */
  inner?: number;
  /* Distance from the innermost ring to the outermost. */
  spread?: number;
  /* The fewest and most lobes a ring can have. */
  lobes?: [number, number];
  /* Curves per ring, and points per curve. Fewer is lighter and coarser. */
  curves?: number;
  points?: number;
  /* A fine toothed border round the outside. */
  border?: boolean;
};

export type Seal = {
  /* One path per ring, innermost first, drawn round (0, 0). */
  rings: string[];
  /* The border, or "" without one. */
  border: string;
  /* Half the width of the square that holds it all. */
  extent: number;
  /* That square as an SVG viewBox. */
  viewBox: string;
};

/* A guilloche, like the security pattern on a banknote. The same seed always
   draws the same seal, on the server and in the browser. */
export function seal(seed: string, o: SealOptions = {}): Seal {
  const n = Math.min(12, Math.max(1, Math.round(o.rings ?? 3)));
  const inner = o.inner ?? 58;
  const spread = o.spread ?? 104;
  const [lo, hi] = o.lobes ?? [7, 12];
  const curves = o.curves ?? 16;
  const points = o.points ?? 180;
  const base = fnv(seed);
  const step = n > 3 ? spread / (n - 1) : 40;
  const rings: string[] = [];
  for (let r = 0; r < n; r++) {
    const h = fnv(`${base}:${r}`);
    const lobes = lo + (h % (hi - lo + 1));
    const phase = (((h >>> 8) % 360) * PI) / 180;
    const amp = Math.min(12 + ((h >>> 16) % 4) * 1.5, step * 0.38);
    const radius = inner + r * step;
    let d = "";
    for (let k = 0; k < curves; k++) {
      const q = (k / curves) * TAU;
      for (let i = 0; i <= points; i++) {
        const t = (i / points) * TAU;
        const rr = radius + amp * sin(lobes * t + q + phase) + (amp / 4) * sin(3 * lobes * t - q);
        d += (i ? "L" : "M") + f1(rr * cos(t)) + "," + f1(rr * sin(t));
      }
      d += "Z";
    }
    rings.push(d);
  }
  const outer = inner + (n - 1) * step + 26;
  let border = "";
  if (o.border !== false) {
    const teeth = 40 + (base % 24);
    for (let k = 0; k < 6; k++) {
      for (let i = 0; i <= 480; i++) {
        const t = (i / 480) * TAU;
        const rr = outer + 3 * sin(teeth * t + k * 1.05);
        border += (i ? "L" : "M") + f1(rr * cos(t)) + "," + f1(rr * sin(t));
      }
      border += "Z";
    }
  }
  const extent = outer + 6;
  return { rings, border, extent, viewBox: `${-extent} ${-extent} ${2 * extent} ${2 * extent}` };
}

export type FieldOptions = { width?: number; height?: number; lines?: number; gap?: number; amp?: number };

/* Fine waves across a whole surface, as one path. The default size is a bank
   card's 856 by 540. */
export function waveField(seed: string, o: FieldOptions = {}) {
  const width = o.width ?? 856;
  const height = o.height ?? 540;
  const gap = o.gap ?? 16;
  const lines = o.lines ?? Math.ceil(height / gap) + 2;
  const amp = o.amp ?? 6;
  const base = fnv(seed);
  const fq = 0.011 + (base % 7) * 0.0012;
  const ph = ((base >>> 3) % 628) / 100; // where along the wave each field starts
  let d = "";
  for (let i = 0; i < lines; i++) {
    for (let x = -10; x <= width + 10; x += 8) {
      const y = -12 + i * gap + amp * sin(x * fq + i * 0.42 + ph) + amp * 0.37 * sin(x * fq * 3.4 - i * 0.31 - ph);
      d += (x === -10 ? "M" : "L") + x + "," + f1(y);
    }
  }
  return d;
}

/* The lines as an SVG, stroked, for a mask. Pure. */
export function maskSvg(viewBox: string, paths: string | string[], width = 1) {
  const list = (Array.isArray(paths) ? paths : [paths]).filter(Boolean);
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}">` +
    list.map((d) => `<path d="${d}" fill="none" stroke="black" stroke-width="${width}"/>`).join("") +
    `</svg>`
  );
}

/* The same, as a blob URL a CSS mask can use. Revoke it when you're done. */
export function maskUrl(viewBox: string, paths: string | string[], width = 1) {
  return URL.createObjectURL(new Blob([maskSvg(viewBox, paths, width)], { type: "image/svg+xml" }));
}

/* ---------- the phone's tilt ---------- */

type Orientation = { requestPermission?: () => Promise<string> };
const orientation = () =>
  (typeof window === "undefined" ? undefined : (window as unknown as { DeviceOrientationEvent?: Orientation }).DeviceOrientationEvent);

/* One listener for the whole page, shared by every surface. The tilt is
   measured from how the phone was held when the first reading came in, and
   that rest slowly follows the hand. */
const gyro = { subs: new Set<(x: number, y: number) => void>(), on: false, got: false, rest: null as null | { b: number; g: number } };

function onTurn(e: DeviceOrientationEvent) {
  if (e.beta == null || e.gamma == null) return;
  const rest = (gyro.rest ??= { b: e.beta, g: e.gamma });
  rest.b += (e.beta - rest.b) * 0.004;
  rest.g += (e.gamma - rest.g) * 0.004;
  let dx = e.gamma - rest.g;
  let dy = e.beta - rest.b;
  const ang = screen.orientation?.angle ?? 0; // keep left as left in landscape
  if (ang === 90) [dx, dy] = [dy, -dx];
  else if (ang === 270) [dx, dy] = [-dy, dx];
  else if (ang === 180) [dx, dy] = [-dx, -dy];
  gyro.got = true;
  const x = Math.max(-1, Math.min(1, dx / 24)) * 0.85;
  const y = Math.max(-1, Math.min(1, -dy / 24)) * 0.85;
  gyro.subs.forEach((fn) => fn(x, y));
}

function listen() {
  if (gyro.on || !gyro.subs.size) return;
  gyro.on = true;
  window.addEventListener("deviceorientation", onTurn);
}

export function onGyro(fn: (x: number, y: number) => void) {
  if (!orientation()) return () => {};
  gyro.subs.add(fn);
  listen(); // Android and the like just send readings. iOS sends nothing until it's asked.
  return () => {
    gyro.subs.delete(fn);
    if (!gyro.subs.size && gyro.on) {
      window.removeEventListener("deviceorientation", onTurn);
      gyro.on = false;
      gyro.rest = null;
    }
  };
}

/* iOS only sends readings after a tap asks for them. Desktop Chrome has the
   same function but no sensor, so this only says yes on a touch screen that
   has sent nothing after a moment. */
export function watchGyroPermission(onNeeded: (needed: boolean) => void, wait = 1200) {
  const doe = orientation();
  if (typeof doe?.requestPermission !== "function" || !matchMedia("(pointer: coarse)").matches || reduced()) return () => {};
  const t = window.setTimeout(() => !gyro.got && onNeeded(true), wait);
  return () => window.clearTimeout(t);
}

/* Call from the tap itself. */
export function askGyro() {
  const doe = orientation();
  doe?.requestPermission?.()
    .then((p) => {
      if (p === "granted") listen();
    })
    .catch(() => {});
}

/* ---------- tilt ---------- */

export type TiltOptions = {
  /* A slow drift when nobody's touching it. */
  drift?: boolean;
  /* Follow the phone's tilt. */
  gyro?: boolean;
};

/* Leans towards the pointer, a finger or the phone's tilt, and writes where it
   is to the stage as --fx-x and --fx-y (-1 to 1), --fx-m (how far, 0 to 1) and
   --fx-a (which way, an angle). CSS does the rest.

   The pointer is read on the stage, which must never move, so the tilt can't
   feed back into its own measurement. A critically damped spring is stepped
   once a frame, so there's no transition to restart and no jolt. It sleeps
   when the stage is off screen. */
export function tilt(stage: HTMLElement, o: TiltOptions = {}) {
  const drift = o.drift ?? true;
  const write = (x: number, y: number) => {
    const m = Math.min(1, Math.hypot(x, y));
    stage.style.setProperty("--fx-x", x.toFixed(4));
    stage.style.setProperty("--fx-y", y.toFixed(4));
    stage.style.setProperty("--fx-m", m.toFixed(4));
    stage.style.setProperty("--fx-a", `${((Math.atan2(y, x) * 180) / PI).toFixed(1)}deg`);
  };
  const clear = () => ["--fx-x", "--fx-y", "--fx-m", "--fx-a"].forEach((p) => stage.style.removeProperty(p));
  if (reduced()) {
    write(0, 0);
    return clear;
  }

  const s = { x: 0, y: 0, vx: 0, vy: 0, tx: 0, ty: 0, gx: 0, gy: 0, active: false, gyro: false, visible: false, t0: performance.now() };
  let raf = 0;
  let last = 0;
  function step(now: number) {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    let gx = 0;
    let gy = 0;
    if (s.active) [gx, gy] = [s.tx, s.ty];
    else if (s.gyro) [gx, gy] = [s.gx, s.gy];
    else if (drift) {
      const t = (now - s.t0) / 1000; // starts at exactly 0
      gx = 0.32 * Math.sin(t * 0.52);
      gy = 0.22 * (Math.sin(t * 0.37 + 0.6) - Math.sin(0.6));
    }
    const k = s.active ? 110 : 26;
    const c = 2 * Math.sqrt(k); // critically damped: no overshoot
    s.vx += (k * (gx - s.x) - c * s.vx) * dt;
    s.x += s.vx * dt;
    s.vy += (k * (gy - s.y) - c * s.vy) * dt;
    s.y += s.vy * dt;
    write(s.x, s.y);
    const settled = !drift && !s.active && !s.gyro && Math.abs(s.x) + Math.abs(s.y) + Math.abs(s.vx) + Math.abs(s.vy) < 0.0005;
    raf = s.visible && !settled ? requestAnimationFrame(step) : 0;
  }
  const wake = () => {
    if (raf || !s.visible) return;
    last = performance.now();
    raf = requestAnimationFrame(step);
  };
  const read = (e: PointerEvent) => {
    const r = stage.getBoundingClientRect();
    s.tx = Math.max(-1, Math.min(1, ((e.clientX - r.left) / r.width) * 2 - 1));
    s.ty = Math.max(-1, Math.min(1, ((e.clientY - r.top) / r.height) * 2 - 1));
    s.active = true;
    wake();
  };
  const release = () => {
    s.active = false;
    wake();
  };
  const releaseTouch = (e: PointerEvent) => e.pointerType !== "mouse" && release();
  const events: [string, (e: PointerEvent) => void][] = [
    ["pointerenter", read],
    ["pointermove", read],
    ["pointerdown", read],
    ["pointerleave", release],
    ["pointercancel", release],
    ["pointerup", releaseTouch],
  ];
  events.forEach(([n, fn]) => stage.addEventListener(n, fn as EventListener));
  const io = new IntersectionObserver(([en]) => {
    s.visible = en.isIntersecting;
    wake();
  });
  io.observe(stage);
  const stopGyro =
    o.gyro === false
      ? () => {}
      : onGyro((x, y) => {
          s.gx = x;
          s.gy = y;
          s.gyro = true;
          wake();
        });
  write(0, 0);

  return () => {
    cancelAnimationFrame(raf);
    io.disconnect();
    stopGyro();
    events.forEach(([n, fn]) => stage.removeEventListener(n, fn as EventListener));
    clear();
  };
}

/* ---------- encrypted words ---------- */

export const GLYPHS = ["✱", "◆", "▮", "◇", "▪"];

export type ScrambleWord = {
  text: string;
  /* Never before this many ms after it was added. */
  delay?: number;
  glyphs?: string[];
  /* Called with a symbol (or null) and a lit flag for every character. */
  onStep: (glyphs: (string | null)[], lit: boolean[]) => void;
};

/* One scheduler for the page, so only one word is ever encrypting. Words take
   turns, with a few seconds between. */
type Entry = ScrambleWord & { from: number; cancel?: () => void };
const words: Entry[] = [];
let turn = 0;
let timer = 0;
let current: Entry | null = null;

function pump() {
  timer = 0;
  if (current || !words.length) return;
  const now = performance.now();
  const ready = words.filter((w) => w.from <= now);
  if (!ready.length) {
    timer = window.setTimeout(pump, Math.min(...words.map((w) => w.from)) - now + 10);
    return;
  }
  turn++;
  const w = ready[turn % ready.length];
  current = w;
  w.cancel = run(w, () => {
    current = null;
    w.cancel = undefined;
    timer = window.setTimeout(pump, 3800 + (turn % 3) * 1300);
  });
}

/* Letters to symbols left to right, a beat, then back with a flash. */
function run(w: Entry, done: () => void) {
  const chars = Array.from(w.text);
  const glyphs = w.glyphs?.length ? w.glyphs : GLYPHS;
  const g: (string | null)[] = chars.map(() => null);
  const lit = chars.map(() => false);
  const live = chars.map((c, i) => (c.trim() ? i : -1)).filter((i) => i >= 0);
  const timers: number[] = [];
  const at = (ms: number, fn: () => void) => void timers.push(window.setTimeout(fn, ms));
  const send = () => w.onStep(g.slice(), lit.slice());
  live.forEach((i, n) =>
    at(n * 45, () => {
      g[i] = glyphs[(chars[i].charCodeAt(0) + n) % glyphs.length];
      send();
    }),
  );
  const back = live.length * 45 + 750;
  live.forEach((i, n) =>
    at(back + n * 65, () => {
      g[i] = null;
      lit[i] = true;
      send();
      at(60, () => {
        lit[i] = false;
        send();
      });
    }),
  );
  at(back + live.length * 65 + 120, done);
  return () => {
    timers.forEach(clearTimeout);
    w.onStep(chars.map(() => null), chars.map(() => false));
  };
}

/* Adds a word to the page's turn. Returns the teardown. Does nothing when
   someone has asked for less motion. */
export function scramble(word: ScrambleWord) {
  if (reduced()) return () => {};
  const entry: Entry = { ...word, from: performance.now() + (word.delay ?? 4000) };
  words.push(entry);
  if (!timer && !current) timer = window.setTimeout(pump, 0);
  return () => {
    const i = words.indexOf(entry);
    if (i >= 0) words.splice(i, 1);
    if (current === entry) {
      entry.cancel?.();
      current = null;
      clearTimeout(timer);
      timer = window.setTimeout(pump, 1200);
    }
    if (!words.length) {
      clearTimeout(timer);
      timer = 0;
    }
  };
}

/* ---------- glow cursor ---------- */

/* A soft light that follows the mouse and lights up the hairline borders of
   anything marked data-fx-rim near it. Mouse and trackpad only: on a touch
   screen, or with less motion asked for, it does nothing. */
export function glowCursor(light: HTMLElement | null, reach = 220) {
  if (typeof window === "undefined" || reduced() || !matchMedia("(hover: hover) and (pointer: fine)").matches) return () => {};
  const root = document.documentElement;
  root.setAttribute("data-fx-cursor", "");
  let x = 0;
  let y = 0;
  let raf = 0;
  const lit = new Set<HTMLElement>();
  function frame() {
    raf = 0;
    if (light) light.style.transform = `translate3d(${x}px, ${y}px, 0)`;
    // Read every rect first, then write, so the browser lays out once.
    const near = Array.from(document.querySelectorAll<HTMLElement>("[data-fx-rim]")).map((el) => [el, el.getBoundingClientRect()] as const);
    for (const [el, r] of near) {
      const dx = Math.max(r.left - x, 0, x - r.right);
      const dy = Math.max(r.top - y, 0, y - r.bottom);
      const d = Math.hypot(dx, dy);
      if (d < reach) {
        el.style.setProperty("--fx-rx", `${(x - r.left).toFixed(0)}px`);
        el.style.setProperty("--fx-ry", `${(y - r.top).toFixed(0)}px`);
        el.style.setProperty("--fx-ro", (1 - d / reach).toFixed(3));
        lit.add(el);
      } else if (lit.has(el)) {
        el.style.setProperty("--fx-ro", "0");
        lit.delete(el);
      }
    }
  }
  const move = (e: PointerEvent) => {
    if (e.pointerType !== "mouse") return;
    x = e.clientX;
    y = e.clientY;
    root.setAttribute("data-fx-cursor", "on");
    if (!raf) raf = requestAnimationFrame(frame);
  };
  const leave = (e: MouseEvent) => {
    if (e.relatedTarget) return;
    root.setAttribute("data-fx-cursor", "");
    lit.forEach((el) => el.style.setProperty("--fx-ro", "0"));
    lit.clear();
  };
  // Scrolling moves the borders under a still mouse.
  const scroll = () => {
    if (root.getAttribute("data-fx-cursor") === "on" && !raf) raf = requestAnimationFrame(frame);
  };
  window.addEventListener("pointermove", move, { passive: true });
  window.addEventListener("scroll", scroll, { passive: true, capture: true });
  document.addEventListener("mouseout", leave);
  return () => {
    cancelAnimationFrame(raf);
    window.removeEventListener("pointermove", move);
    window.removeEventListener("scroll", scroll, { capture: true });
    document.removeEventListener("mouseout", leave);
    root.removeAttribute("data-fx-cursor");
    lit.forEach((el) => ["--fx-rx", "--fx-ry", "--fx-ro"].forEach((p) => el.style.removeProperty(p)));
    if (light) light.style.removeProperty("transform");
  };
}

/* Effects, from the Morris OS guest key card. Opt-in, for special moments only:
   see "Effects" in obvious's CLAUDE.md.

   The hologram is the same blue-violet in every theme, like the golds, so its
   colours are fixed here. An app can set any --fx-* on :root to change them.
   Anything that has to read against the page (the glow on letters, the
   sheen, lit edges) is mixed with the theme's text colour where it's used,
   so it works in light themes as well as dark. */

:where(:root) {
  /* Thin-film colour, pulled to the cool end: ice, periwinkle, orchid, cornflower, cyan, lilac. */
  --fx-film-1: #9fd0ff;
  --fx-film-2: #b3a4ff;
  --fx-film-3: #e2a8ff;
  --fx-film-4: #8fb0ff;
  --fx-film-5: #86e8ff;
  --fx-film-6: #c2b6ff;
  /* The glows. */
  --fx-blue: #698cff;
  --fx-violet: #aa6eff;
  /* Lines and highlights on a dark surface. */
  --fx-light: #eef0ff;

  --fx-border-width: var(--ds-border-heavy);
  --fx-rim-width: var(--ds-border-hairline);
  --fx-rim-reach: 160px;
  --fx-cursor-size: 520px;

  /* Slow things, slower than any duration token. */
  --fx-glow-every: 11s;
  --fx-sheen-every: 9s;
  --fx-border-every: 6s;
}

@keyframes ob-fx-turn { to { transform: rotate(1turn); } }

/* ---------- HoloSurface ---------- */

/* The stage never moves; the pointer is read here. */
.ob-fx-surface { position: relative; touch-action: pan-y; -webkit-tap-highlight-color: transparent; }
.ob-fx-surface-tilt {
  position: relative;
  transform:
    perspective(var(--fx-perspective, 1100px))
    rotateX(calc(var(--fx-y, 0) * var(--fx-tilt, 8deg) * -0.75))
    rotateY(calc(var(--fx-x, 0) * var(--fx-tilt, 8deg)));
  will-change: transform;
}
:where(.ob-fx-surface-tilt) { border-radius: var(--ds-radius-xl); }
.ob-fx-surface-light, .ob-fx-surface-rim { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; }
.ob-fx-surface-light { overflow: hidden; }
.ob-fx-surface-light > span {
  position: absolute; inset: -60%;
  background: radial-gradient(closest-side, color-mix(in srgb, var(--fx-light) 8%, transparent), color-mix(in srgb, var(--fx-light) 2%, transparent) 50%, transparent);
  transform: translate3d(calc(var(--fx-x, 0) * 22%), calc(var(--fx-y, 0) * 22%), 0);
}
/* The edge facing the light: clear on the far side, bright on the near one. */
.ob-fx-surface-rim {
  padding: var(--ds-border-thick);
  background: conic-gradient(from calc(var(--fx-a, -90deg) + 30deg), transparent, color-mix(in oklab, var(--fx-light) 80%, var(--fx-violet)) 60deg, transparent 120deg);
  -webkit-mask: linear-gradient(black 0 0) content-box, linear-gradient(black 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(black 0 0) content-box exclude, linear-gradient(black 0 0);
  opacity: calc(0.15 + var(--fx-m, 0) * 0.85);
}

/* ---------- Holo ---------- */

.ob-fx-holo { position: relative; display: block; width: 100%; color: var(--fx-light); }
.ob-fx-holo > div { position: absolute; inset: 0; }
.ob-fx-holo:not(svg):not([data-ready]) > div { visibility: hidden; }
/* Scoped to the div layers: on the SVG version this would override its mask attribute. */
div.ob-fx-holo-base, div.ob-fx-holo-colour {
  -webkit-mask: var(--fx-mask) center / 100% 100% no-repeat;
  mask: var(--fx-mask) center / 100% 100% no-repeat;
}
/* The engraving, faint. */
div.ob-fx-holo-base { background: currentColor; opacity: var(--fx-holo-base, 0.12); }
/* The same lines over colour, so the colour only shows on the lines and where the light is. */
div.ob-fx-holo-colour { overflow: hidden; }
.ob-fx-holo-colour { opacity: var(--fx-holo-strength, 1); }
.ob-fx-holo-counter { position: absolute; inset: 0; }
.ob-fx-holo-film {
  position: absolute; left: -80%; top: -80%; width: 260%; height: 260%;
  -webkit-mask: radial-gradient(closest-side, black, color-mix(in srgb, black 60%, transparent) 18%, color-mix(in srgb, black 18%, transparent) 36%, transparent 52%);
  mask: radial-gradient(closest-side, black, color-mix(in srgb, black 60%, transparent) 18%, color-mix(in srgb, black 18%, transparent) 36%, transparent 52%);
  transform: translate3d(calc(var(--fx-x, 0) * 13%), calc(var(--fx-y, 0) * 8.5%), 0);
  opacity: calc(0.4 + var(--fx-m, 0) * 0.6);
  will-change: transform, opacity;
}
.ob-fx-holo-bands {
  position: absolute; inset: -20%;
  background: repeating-linear-gradient(104deg, var(--fx-film-1) 0, var(--fx-film-2) 3.5%, var(--fx-film-3) 7%, var(--fx-film-4) 10.5%, var(--fx-film-5) 14%, var(--fx-film-6) 17.5%, var(--fx-film-1) 21%);
  transform: translate3d(calc((var(--fx-x, 0) * 0.9 + var(--fx-y, 0) * 0.5) * 9%), 0, 0);
  will-change: transform;
}

/* SVG children: the same thing drawn with an SVG mask. */
svg.ob-fx-holo { overflow: visible; }
.ob-fx-holo-svg .ob-fx-holo-base { opacity: var(--fx-holo-base, 0.12); fill: currentColor; }
.ob-fx-holo-svg .ob-fx-holo-base [stroke]:not([stroke="none"]) { stroke: currentColor; }
.ob-fx-holo-svg .ob-fx-holo-base [fill]:not([fill="none"]) { fill: currentColor; }
.ob-fx-holo-svg-bands, .ob-fx-holo-svg-light { transform-box: fill-box; transform-origin: center; }
.ob-fx-holo-svg-bands { transform: translate(calc((var(--fx-x, 0) * 0.9 + var(--fx-y, 0) * 0.5) * 6%), 0); }
.ob-fx-holo-svg-light {
  transform: translate(calc(var(--fx-x, 0) * 13%), calc(var(--fx-y, 0) * 8.5%));
  opacity: calc(0.4 + var(--fx-m, 0) * 0.6);
}

/* ---------- Guilloche ---------- */

.ob-fx-guilloche { position: relative; display: block; width: 100%; }
/* Outer rings slide further than inner ones as it tilts. */
.ob-fx-guilloche-ring {
  position: absolute; inset: 0;
  translate: calc(var(--fx-x, 0) * var(--fx-depth, 0) * -1%) calc(var(--fx-y, 0) * var(--fx-depth, 0) * -0.75%);
}
.ob-fx-guilloche-ring > .ob-fx-holo { height: 100%; }
/* Ring against ring, very slowly. The light is turned back against the spin, so it stays put. */
.ob-fx-guilloche-ring[data-spin] { animation: ob-fx-turn var(--fx-spin) linear infinite; }
.ob-fx-guilloche-ring[data-spin="reverse"] { animation-direction: reverse; }
.ob-fx-guilloche-ring[data-spin] .ob-fx-holo-counter { animation: ob-fx-turn var(--fx-spin) linear infinite reverse; }
.ob-fx-guilloche-ring[data-spin="reverse"] .ob-fx-holo-counter { animation-direction: normal; }

/* ---------- EncryptedText ---------- */

.ob-fx-enc { position: relative; }
.ob-fx-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.ob-fx-enc-letters > span {
  position: relative;
  transition: color var(--ds-duration-slow) var(--ds-ease-out), text-shadow var(--ds-duration-slow) var(--ds-ease-out);
}
/* The letter stays where it is, invisible, holding its width; its symbol sits on top. */
.ob-fx-enc-letters > [data-g] { color: transparent; text-shadow: none; transition: none; }
.ob-fx-enc-letters > [data-g]::after {
  content: attr(data-g);
  position: absolute; left: 50%; top: 0;
  transform: translateX(-50%) scale(0.66); transform-origin: 50% 60%;
  color: color-mix(in oklab, var(--fx-violet) 55%, var(--fx-ink, var(--ds-color-text)));
  text-shadow: 0 0 0.35em color-mix(in srgb, var(--fx-violet) 55%, transparent);
}
.ob-fx-enc-letters > [data-lit] { text-shadow: 0 0 0.3em color-mix(in srgb, var(--fx-blue) 80%, transparent); transition: none; }

/* ---------- GlowText ---------- */

.ob-fx-glow-text { position: relative; display: inline-block; max-width: 100%; isolation: isolate; overflow-x: clip; }
.ob-fx-glow {
  position: absolute; inset: -80% 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(38% 46% at 36% 52%, color-mix(in srgb, var(--fx-blue) 22%, transparent), transparent 72%),
    radial-gradient(34% 44% at 66% 48%, color-mix(in srgb, var(--fx-violet) 20%, transparent), transparent 72%);
  animation: ob-fx-glow var(--fx-glow-every) ease-in-out infinite alternate;
}
@keyframes ob-fx-glow { from { transform: translate3d(-4%, 3%, 0); } to { transform: translate3d(4%, -3%, 0); } }
/* The words stay solid in the theme's text colour. The glow on them is thin. */
.ob-fx-glow-ink {
  color: var(--fx-ink, var(--ds-color-text));
  text-shadow:
    0 0 0.04em color-mix(in srgb, var(--fx-blue) 50%, transparent),
    0 0 0.24em color-mix(in srgb, var(--fx-blue) 32%, transparent),
    0 0 0.6em color-mix(in srgb, var(--fx-violet) 18%, transparent);
}
/* The sheen is a copy of the words in a lighter colour, seen through a band
   that crosses them. The band moves one way and the copy the other, so the
   letters stay still and only transform changes. */
.ob-fx-sheen, .ob-fx-sheen-band { position: absolute; inset: 0; pointer-events: none; }
.ob-fx-sheen { overflow: hidden; }
.ob-fx-sheen-band {
  -webkit-mask: linear-gradient(100deg, transparent 38%, black 50%, transparent 62%) no-repeat;
  mask: linear-gradient(100deg, transparent 38%, black 50%, transparent 62%) no-repeat;
  transform: translateX(-101%);
  animation: ob-fx-sheen var(--fx-sheen-every) ease-in-out var(--ds-duration-slowest) infinite;
}
.ob-fx-sheen-text {
  display: block;
  color: color-mix(in oklab, var(--fx-light) 45%, color-mix(in oklab, var(--fx-violet) 35%, var(--fx-ink, var(--ds-color-text))));
  transform: translateX(101%);
  animation: ob-fx-sheen-back var(--fx-sheen-every) ease-in-out var(--ds-duration-slowest) infinite;
}
@keyframes ob-fx-sheen { 0% { transform: translateX(-101%); } 20%, 100% { transform: translateX(101%); } }
@keyframes ob-fx-sheen-back { 0% { transform: translateX(101%); } 20%, 100% { transform: translateX(-101%); } }

/* ---------- BorderLight ---------- */

.ob-fx-border-light { position: relative; display: inline-block; border-radius: var(--fx-radius, var(--ds-radius-md)); isolation: isolate; }
.ob-fx-border-light.is-block { display: block; }
.ob-fx-border-light-ring {
  position: absolute; inset: 0; border-radius: inherit; padding: var(--fx-border-width);
  overflow: hidden; pointer-events: none; container-type: size;
  -webkit-mask: linear-gradient(black 0 0) content-box, linear-gradient(black 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(black 0 0) content-box exclude, linear-gradient(black 0 0);
}
/* A square bigger than the diagonal, turning, with the light in one corner of it. */
.ob-fx-border-light-ring > span {
  position: absolute; left: 50%; top: 50%;
  width: 150cqmax; height: 150cqmax; margin: -75cqmax 0 0 -75cqmax;
  background: conic-gradient(
    transparent 0deg 200deg,
    color-mix(in srgb, var(--fx-violet) 60%, transparent) 290deg,
    color-mix(in oklab, var(--fx-light) 65%, color-mix(in oklab, var(--fx-blue) 40%, var(--fx-ink, var(--ds-color-text)))) 345deg,
    transparent 360deg
  );
  animation: ob-fx-turn var(--fx-border-every) linear infinite;
}

/* ---------- GlowCursor ---------- */

.ob-fx-cursor { display: none; }
:root[data-fx-cursor] .ob-fx-cursor {
  display: block; position: fixed; z-index: var(--ds-z-toast);
  left: calc(var(--fx-cursor-size) / -2); top: calc(var(--fx-cursor-size) / -2);
  width: var(--fx-cursor-size); height: var(--fx-cursor-size);
  border-radius: 50%; pointer-events: none; mix-blend-mode: screen;
  background: radial-gradient(closest-side, color-mix(in srgb, var(--fx-blue) 13%, transparent), color-mix(in srgb, var(--fx-violet) 5%, transparent) 55%, transparent);
  opacity: 0;
  transition: opacity var(--ds-duration-slow) var(--ds-ease-out);
}
:root[data-fx-cursor="on"] .ob-fx-cursor { opacity: 1; }
:where(:root[data-fx-cursor] [data-fx-rim]) { position: relative; }
/* The rim is drawn over the element's own hairline border, lit where the mouse is. */
:root[data-fx-cursor] [data-fx-rim]::after {
  content: ""; position: absolute; inset: calc(-1 * var(--fx-rim-width)); border-radius: inherit;
  padding: var(--fx-rim-width); pointer-events: none;
  background: radial-gradient(var(--fx-rim-reach) circle at var(--fx-rx, -100vw) var(--fx-ry, -100vh), color-mix(in oklab, var(--fx-blue) 65%, var(--fx-ink, var(--ds-color-text))), transparent);
  -webkit-mask: linear-gradient(black 0 0) content-box, linear-gradient(black 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(black 0 0) content-box exclude, linear-gradient(black 0 0);
  opacity: var(--fx-ro, 0);
}

/* ---------- less motion ---------- */

/* Everything stops in its final state: flat, lit evenly, the light on the
   border parked at the top right. */
@media (prefers-reduced-motion: reduce) {
  .ob-fx-glow, .ob-fx-guilloche-ring, .ob-fx-holo-counter, .ob-fx-border-light-ring > span { animation: none !important; }
  .ob-fx-sheen { display: none; }
  .ob-fx-border-light-ring > span { transform: rotate(45deg); }
  .ob-fx-surface-tilt, .ob-fx-holo-film, .ob-fx-holo-bands { will-change: auto; }
}
